import math
import random
from dataclasses import dataclass
from typing import Dict, FrozenSet, List, Set, Tuple

@dataclass
class Replica:
    rid: str
    key: str
    node: str
    gen: int
    state: str
    content: str
    families: FrozenSet[int]
    readers: int = 0
    cache_pin: bool = False
    alloc_alive: bool = True

class Store:
    def __init__(self) -> None:
        self.dir: Dict[str, Set[str]] = {}
        self.reps: Dict[str, Replica] = {}
        self.free_log: List[Tuple[str, int]] = []
        self.next_id = 0

    def add(self, key: str, node: str, gen: int, state: str, content: str,
            families: FrozenSet[int], advertise: bool = False) -> str:
        rid = 'r' + str(self.next_id)
        self.next_id += 1
        self.reps[rid] = Replica(rid, key, node, gen, state, content, families)
        if advertise:
            self.dir.setdefault(key, set()).add(rid)
        return rid

    def advertise(self, key: str, rid: str) -> None:
        self.dir.setdefault(key, set()).add(rid)

    def usable_rids(self, key: str, req_fams: FrozenSet[int]) -> List[str]:
        out = []
        for rid in sorted(self.dir.get(key, set())):
            r = self.reps.get(rid)
            if r is None:
                continue
            ok = r.alloc_alive and r.state == 'READY'
            ok = ok and r.key == key and r.content == key
            ok = ok and req_fams.issubset(r.families)
            if ok:
                out.append(rid)
        return out

    def acquire(self, keys: List[str], req_fams: FrozenSet[int],
                max_blocks: int = -1) -> Tuple[int, List[str]]:
        limit = len(keys) if max_blocks < 0 else max(0, min(len(keys), max_blocks))
        chosen: List[str] = []
        for j in range(limit):
            cand = self.usable_rids(keys[j], req_fams)
            if not cand:
                break
            chosen.append(cand[0])
        for rid in chosen:
            self.reps[rid].readers += 1
        return len(chosen), chosen

    def release(self, rid: str) -> None:
        r = self.reps[rid]
        if r.readers <= 0:
            raise RuntimeError('release without a reader')
        r.readers -= 1

    def _retire(self, rid: str) -> None:
        r = self.reps[rid]
        r.state = 'RETIRED'
        r.alloc_alive = False
        for key in list(self.dir):
            self.dir[key].discard(rid)

    def safe_evict(self, rid: str) -> None:
        r = self.reps[rid]
        if r.state != 'READY' or r.readers != 0 or r.cache_pin:
            raise RuntimeError('unsafe eviction rejected')
        self.free_log.append((rid, r.readers))
        self._retire(rid)

    def unsafe_evict(self, rid: str) -> None:
        r = self.reps[rid]
        self.free_log.append((rid, r.readers))
        self._retire(rid)

    def freed_with_readers(self) -> List[Tuple[str, int]]:
        return [(rid, n) for rid, n in self.free_log if n > 0]

def oracle_prefix(store: Store, keys: List[str], req_fams: FrozenSet[int],
                  max_blocks: int) -> int:
    limit = max(0, min(len(keys), max_blocks))
    ready_keys = set()
    for r in store.reps.values():
        if not r.alloc_alive or r.state != 'READY':
            continue
        if r.content != r.key or not req_fams.issubset(r.families):
            continue
        if r.rid in store.dir.get(r.key, set()):
            ready_keys.add(r.key)
    p = 0
    for key in keys[:limit]:
        if key not in ready_keys:
            break
        p += 1
    return p

def faulty_dir_presence(store: Store, keys: List[str]) -> int:
    p = 0
    for key in keys:
        if store.dir.get(key):
            p += 1
        else:
            break
    return p

def faulty_any_family(store: Store, keys: List[str]) -> int:
    keys_with_any = set()
    for bucket in store.dir.values():
        for rid in bucket:
            r = store.reps[rid]
            if r.alloc_alive and r.state == 'READY' and r.content == r.key:
                keys_with_any.add(r.key)
    p = 0
    for key in keys:
        if key not in keys_with_any:
            break
        p += 1
    return p

def common_position(limit: int, allowed_sets: List[Set[int]]) -> int:
    allowed = set(range(limit + 1))
    for s in allowed_sets:
        allowed &= s
    if not allowed:
        return -1
    return max(allowed)

def faulty_min_of_maxima(allowed_sets: List[Set[int]]) -> int:
    return min(max(s) for s in allowed_sets)

def remote_better(recompute_ms: float, transfer_ms: float, extra_ms: float) -> bool:
    return transfer_ms + extra_ms < recompute_ms

def main() -> None:
    keys = ['b0', 'b1', 'b2', 'b3', 'b4']
    s = Store()
    r0 = s.add('b0', 'n0', 1, 'READY', 'b0', frozenset((0, 1)), True)
    r1 = s.add('b1', 'n1', 1, 'READY', 'b1', frozenset((0, 1)), True)
    s.add('b2', 'n2', 1, 'READY', 'b2', frozenset((0,)), True)
    s.add('b2', 'n3', 2, 'READY', 'stale', frozenset((0, 1)), True)
    s.add('b3', 'n0', 1, 'READY', 'b3', frozenset((0, 1)), True)
    s.add('b4', 'n1', 1, 'BUILDING', 'b4', frozenset((0, 1)), False)
    p, holds = s.acquire(keys, frozenset((0, 1)))
    ref = oracle_prefix(s, keys, frozenset((0, 1)), len(keys))
    if p != 2 or ref != 2 or len(holds) != 2:
        raise AssertionError('partial-family or stale-content case')
    if s.reps[r0].readers != 1 or s.reps[r1].readers != 1:
        raise AssertionError('reader lease not installed')
    bad_family = faulty_any_family(s, keys)
    if not bad_family > p:
        raise AssertionError('family negative control not exposed')
    for rid in holds:
        s.release(rid)

    ghost = Store()
    ghost.add('g0', 'n0', 1, 'BUILDING', 'g0', frozenset((0, 1)), True)
    p0, h0 = ghost.acquire(['g0', 'g1'], frozenset((0, 1)))
    bad_dir = faulty_dir_presence(ghost, ['g0', 'g1'])
    if p0 != 0 or h0 or bad_dir != 1:
        raise AssertionError('directory-presence negative control')

    full = set(range(13))
    rec = {4, 8, 12}
    win = {8, 12}
    if common_position(8, [full, rec, win]) != 8:
        raise AssertionError('common recovery intersection')
    if common_position(5, [set(range(4)), {4, 5}]) != -1:
        raise AssertionError('non-contiguous family positions')
    if faulty_min_of_maxima([set(range(4)), {4, 5}]) != 3:
        raise AssertionError('position-set negative control not exposed')

    rng = random.Random(13013)
    matrix_cases = 0
    for case in range(40):
        ks = ['c' + str(case) + '-' + str(j) for j in range(6)]
        st = Store()
        for j, key in enumerate(ks):
            for _ in range(rng.randrange(0, 4)):
                state = rng.choice(['READY', 'READY', 'BUILDING', 'RETIRED'])
                content = key if rng.random() > 0.3 else key + '-stale'
                fams = frozenset(f for f in (0, 1) if rng.random() < 0.7)
                rid = st.add(key, 'n' + str(rng.randrange(3)), 1, state,
                             content, fams, False)
                if rng.random() < 0.85:
                    st.advertise(key, rid)
        for fams in (frozenset((0,)), frozenset((0, 1))):
            for limit in (0, rng.randrange(0, 7), 6):
                p, holds = st.acquire(ks, fams, limit)
                ref = oracle_prefix(st, ks, fams, limit)
                if p != ref or len(holds) != p:
                    raise AssertionError('random oracle mismatch')
                for rid, r in st.reps.items():
                    expected = 1 if rid in holds else 0
                    if r.readers != expected:
                        raise AssertionError('reader accounting mismatch')
                for rid in holds:
                    st.release(rid)
        matrix_cases += 1

    lease = Store()
    lr = lease.add('k0', 'n0', 1, 'READY', 'k0', frozenset((0, 1)), True)
    _, lh = lease.acquire(['k0'], frozenset((0, 1)))
    rejected = False
    try:
        lease.safe_evict(lr)
    except RuntimeError:
        rejected = True
    if not rejected:
        raise AssertionError('safe eviction did not reject a reader')
    lease.unsafe_evict(lr)
    violations = lease.freed_with_readers()
    if not violations:
        raise AssertionError('unsafe release negative control not exposed')
    lease.release(lr)

    clean = Store()
    cr = clean.add('k1', 'n0', 1, 'READY', 'k1', frozenset((0, 1)), True)
    clean.acquire(['k1'], frozenset((0, 1)))
    clean.release(cr)
    clean.safe_evict(cr)
    if clean.freed_with_readers():
        raise AssertionError('clean eviction recorded a reader')

    transfer_ms = (512 * 1024 * 1024) / (20 * 1024 ** 3) * 1000.0
    if not math.isclose(transfer_ms, 25.0, rel_tol=1e-12):
        raise AssertionError('transfer lower bound')
    if remote_better(30.0, transfer_ms, 15.0):
        raise AssertionError('recompute should win at 30 ms')
    if not remote_better(180.0, transfer_ms, 15.0):
        raise AssertionError('remote should win at 180 ms')
    demand = 4.0 * 0.3 * 0.5
    if not math.isclose(demand, 0.6, rel_tol=1e-12):
        raise AssertionError('network demand')

    print('deterministic matrix: p=' + str(p) + ', oracle=' + str(ref)
          + ', family_any=' + str(bad_family))
    print('directory negative: correct=0, faulty=' + str(bad_dir))
    print('common position: intersection=8, empty=-1, faulty_min=3')
    print('random matrix cases checked: ' + str(matrix_cases))
    print('negative controls detected: dir-presence, family-any, position-min, unsafe-free')
    print('cost reversal: transfer=25 ms; remote=40 ms vs recompute 30/180 ms')
    print('scope: CPU logical/read-only model; no GPU, NIC, RDMA or SLO measurement')

if __name__ == '__main__':
    main()
